declare const createNumberRangeValidator: (valueRange: ValueRange, units: Units) => URValidatorFn;
declare const createExpressionValidator: (minLength?: number, maxLength?: number) => InternalURValidatorFn;
declare const createIntegerValidator: () => URValidatorFn;

